  Gt = `Включени събития:`,
  Kt = `Позволяване на всички отговарящи събития от отличените приложения да се появяват в графика`,
  qt = `Графикът винаги ще посочва всяко отговарящо събитие от базовата група и всички събития от дадена колекция. Поставянето на отметка в това поле позволява на събитията от всички включени приложения също да се появяват в графика. С премахването на отметката Вие се ограничавате само до събития, асоциирани с хостване на групи или събития, изрично изброени в колекции.`,
  Jt = `Предупреждение: Началният час в графика е преди стартовото време на събитието. Сигурни ли сте, че това е правилно?`,
