  gn = `Тези събития са насрочени за в бъдеще, но няма да бъдат видими до стартовото време. Не се изискват по-нататъшни действия. `,
  _n = `Скрито, непубликувано`,
  vn = `Това събитие е в чернови режим. Никой, освен членовете на обществения Ви екип не може да вижда това събитие. Всички промени ще останат скрити, докато не предприемете действие да публикувате събитието.`,
