  Tn = `Изискваме да бъде зададе суетен адрес на страницата за разпродажба, за да сте способни да я публикувате. Този суетен адрес се използва за създаването на адрес за разпродажбата, осигуряващ достъп за клиентите.`,
  En = `Изискваме да бъде обновен суетния адрес на началната страницата, за да сте способни да я публикувате. Този суетен адрес се използва за създаването на адрес, осигуряващ достъп за клиентите.`,
  Dn = `Преглед на разпродажба`,
