  Kn = `Видимост`,
  qn = `Заглавие на секцията`,
  Jn = `Изберете от списък с предварително преведени заглавия, които да се изобразяват в горната част на тази секция, или подберете „Персонализирано заглавие“, за да въведете свое собствено. Започнете да пишете в полето, за да намерите предварително преведено заглавие.`,
  Yn = `Подзаглавие`,
  Xn = `(Макс. %1$s символа. Появява се в най-горната част на страницата с подробности за събитие или анонс)`,
