  Qn = `Версия 2 на началната страница на създателите предоставя гъвкав начин за персонализиране на съответната такава за издател, разработчик или поредица.`,
  $n = `Тази страница не е видима. Първо я публикувайте, а след това тя може да бъде зададена като текуща страница на създател.`,
  er = `Тази страница <1>не е</1> текущата Ви начална такава на създател. Използвайте <2>таблото за началната страница на създател</2>, така че да активирате това.`,
  tr = `Тази страница е текущата Ви начална такава на създател. Може да управлявате това от Вашето <1>табло за началната страница на създател</1>.`,
  nr = `Аватар`,
