  ir = `Лозунг`,
  ar = `Редактиране: <1>Табло на началната страница за създател</1>`,
  or = `Добре дошли!`,
  sr = `<1>Вашите игри</1> — Игрите Ви се е появяват в списъка със свързани приложения по-долу и са готови за използване. Просто добавете и конфигурирайте секциите по-долу, така че да организирате рекламирането на Вашите игри, сваляеми съдържания, демота и саундтракове по начина, който най-добре отговаря на нуждите Ви.`,
  cr = `<1>Свързване на още игри</1> — Ако в този списък по-долу липсват игри, това означава, че не сте ги свързали към тази начална страница на създателя. За инструкции относно това как да свържете игри към началната Ви страница, моля, вижте документацията <2>„Начални страници за издатели и разработчици“</2>.`,
  lr = `<1>Установка по подразбиране</1> — По-долу ще намерите набор от предварително конфигурирани секции по подразбиране, които да отличават Вашите популярни, препоръчани и скорошни издания. Не се колебайте да използвате толкова малко или много от настройките по подразбиране, колкото желаете.`,
  ur = `Вижте документацията за още подробности`,
  dr = `Категория: %1$s`,
  fr = `Грешка при клониране на събитие`,
  pr = `Натъкнахме се на грешка по време на подготвителния процес за клониране: %1$s`,
  mr = `Грешка при публикуване на събитие`,
  hr = `Натъкнахме се на грешка по време на подготвителния процес за публикуване на събитието: %1$s`,
  gr = `Тази разпродажба има голям списък със свързани артикули, така че таговете на артикулите ѝ се възстановяват от магазина. Това може да отнеме известно време.`,
  _r = `Не успяхме да възстановим таговете на артикулите за тази разпродажба от магазина, така че редакторът не може да бъде отворен безопасно. Моля, презаредете страницата, за да опитате отново.`,
  vr = `%1$s артикула в списъка със свързани артикули не можаха да бъдат заредени от магазина, най-вероятно защото са забранени или вече не са в продажба. Техните тагове не са възстановени, така че е възможно да изчезнат от филтрираните по таг секции (можете да продължите да работите нормално, ако са забранени и т.н.): %2$s. `,
  yr = `Стартова дата на събитие`,
