  Dr = `Можете да направите събитието видимо преди стартовата дата, ако желаете да осведомите играчите, че то предстои и им позволете да се регистрират за известия.`,
  Or = `Можете да направите анонса видим преди стартовата дата, ако желаете да осведомите играчите, че събитието Ви предстои и им позволете да се регистрират за известия.`,
  kr = `Крайна дата на събитие`,
