  Ki = `Запазване на новите редове`,
  qi = `В HTML новите редове обикновено нямат значение, но в BBCode те ще се показва като празни редове. Ако сте ползвали таговете <p> или <br>, оставете тази отметка празна. Ако обикновено използвате софтуер за блог, който автоматично добавя <br> за нов ред, би било добре да поставите отметка в това поле.`,
