  rf = `Запазването е завършено успешно.`,
  af = `Промените трябва да са незабавно видими за Steam клиентите.`,
  of = `Следните грешки в текущото събитие предотвратяват запазването на това предходно публикувано такова. Моля, поправете ги и пак опитайте да запазите събитието.`,
  sf = `Следните са предупреждения с текущото събитие, които могат да бъдат заобиколени и не предотвратяват запазването, но въпреки това, препоръчваме да ги отстраните.`,
  cf = `Прескачане на предупрежденията и запазване въпреки това…`,
