  Ef = `Насрочено събитие (скрито, публикувано)`,
  Df = `Това е списък от събития, които са насрочени и готови автоматично да станат видим при посоченото бъдещо време. Можете да продължите редактирането на тези събития, ако е нужно да правите обновления.`,
  Of = `Невписани събития (публикувани, видими с директна връзка)`,
  kf = `Тези събития са видими само за онези, които разполагат с директна връзка към събитието. Те не се появяват в никакви списъци, нито пък се свързват автоматично с някоя система за събития.`,
  Af = `Публично видими събития (видими, публикувани)`,
