  jp = `© Valve Corporation. П.К. 1688 Белвю, Вашингтон 98009.`,
  Mp = `Всички права запазени. Всички търговски марки принадлежат на съответните им собственици в САЩ и други държави.`,
  Np = `Пращане на изпитателно е-писмо`,
  Pp = `Не може да се изпрати изпитателно е-писмо. Е-пощата Ви не е потвърдена със Steam. Моля, потвърдете е-пощата тук: %1$s`,
  Fp = `Промените по е-пощата не са запазени. Моля, запазете промените, преди да задействате е-писмото за преглед.`,
  Ip = `Изпращане на е-писмо към е-пощата, асоциирана с акаунта Ви? Ако това е грешно, обновете своята е-поща тук: %1$s`,
