  Qp = `Потребители на игри, свързани към началната Ви страница за създател %1$s`,
  $p = `Няма свързана начална страница за създател към тази игра, ограничавайки потенциала за е-писма. Научете още тук: %1$s`,
  em = `Езиковото съдържание е непълно за %1$s. Попълнени са %2$s от %3$s секции.`,
  tm = `Е-писмото изисква марково изображение на английски. Е-писмото не може да бъде изпратено без художествено творчество на английски.`,
  nm = `Трябва да се избере поне една група, която да получи е-писмото`,
  rm = `Е-писмото няма никакъв текст`,
  im = `В секцията за получатели трябва да изберете поне една отметка между правата за разработчик или издател.`,
