  om = `Е-писмата не могат да бъдат установявани или изпращани, докато същественото събитие не е публикувано и излязло. Моля, първо публикувайте събитието.`,
  sm = `Е-писмото има локализация на %1$s без съответстващо марково художествено творчество за езика. Това ще използва резервния вариант, показвайки английското марково художествено творчество.`,
  cm = `Е-писмото има локализация на %1$s и %2$s без съответстващо марково художествено творчество за тези езици. Това ще използва резервния вариант, показвайки английското марково художествено творчество.`,
  lm = `Е-писмото има локализация на %1$s, %2$s и още %3$s езика без съответстващо марково художествено творчество за тях. Това ще използва резервния вариант, показвайки английското марково художествено творчество.`,
  um = `Е-писмото разполага с локализация за %1$s език, но няма съответстващо марково художествено творчество за него.`,
