  ZA = `Инструмент за качване на икони за подменю`,
  QA = `Качете локализирана икона за този артикул от подменюто: %1$s`,
  $A = `Въвеждане на локализирано име…`,
  ej = `Намиране в разпродажбата`,
  tj = `Инструмент, който Ви позволява да проверявате специфични приложения/пакети/комплекти из цялата страница на разпродажбата`,
  nj = `Потърсете приложение на страницата по номера или името му. Това търсене преглежда само в разпродажбата за приложения, комплекти или пакети, които са изрично отличени на тази нейна страница чрез съответната секция или присъстват неявно, бидейки част от самите раздели.`,
  rj = `Въведете име или №`,
  ij = `Няма съответстващ артикул`,
  aj = `Търсенето няма да различава главни от малки букви, или ще търси по № на приложението/№ на пакета или № комплекта`,
  oj = `Артикул: %1$s; Тип: %2$s`,
