  lj = `Артикулът е намерен в следните секции на разпродажбата:`,
  uj = `Артикулът е намерен в следните раздели:`,
  dj = `Искате да премахнете артикула от всички секции в разпродажбата на тази страница?`,
  fj = `Зареждане на всичката информация за приложения, комплекти и пакети`,
  pj = `Продуктът се появява в списъка със свързани приложения.`,
