  hj = `Преглед на живо`,
  gj = `Отваря прозорец, който показва разпродажбата и се обновява, докато правите промени.`,
  _j = `Разкриване`,
  vj = `Разкрива и отличава тази секция в разпродажбата`,
  yj = `Изскачащ прозорец (настолен компютър)`,
  bj = `Изскачащ прозорец (мобилно у-во)`,
  xj = `Изскачащ прозорец (Steam Deck)`,
  Sj = `Нов раздел`,
  Cj = `Отворете „Преглед на живо“ в изскачащ прозорец на браузъра. Ако не е поставена отметка, се отваря в нов раздел, което Ви позволява малко по-лесно да използвате инструментите за разработчици и включва характеристики, като например мобилния им режим.`,
  wj = `Изнасяне на местонахожденията за игри`,
