  RP = `Прилага филтри след зареждане на подробностите за артикули, за да се определи дали трябва да бъдат изобразявани в тази секция. Ето например, ако дадена игра е маркирана като „Очаквайте скоро“ и не искате да я включвате в тази секция, докато не е издадена, можете да използвате този филтър, за да постигнете това.`,
