  II = `Произволно издърпва от всички възможни артикули`,
  LI = `Когато това е зададено, няма просто да се грабват най-продаваните артикули, които съответстват на този таг или категория. Произволно ще се избират от всички възможни съответстващи артикули.`,
  RI = `Изобразява на ротационна капсула`,
  zI = `Когато е избрано, вместо да са представени в решетка от капсули, ще бъдат показвани като хоризонтална ротационна капсула. Тя може да бъде движена наляво и надясно помежду им, за да се виждат допълнителни артикули.`,
  BI = `Стил на ротационната капсула за мобилни у-ва`,
