  KI = `Ротационна капсула на цяла страница`,
  qI = `Всеки елемент от ротационната капсула изпълва пространството на мобилното устройство и има индикатор в навигационния път, посочващ, че има още артикули в нея.`,
  JI = `Включване на автоматичен преход`,
  YI = `Когато е избрано, ротационната капсула ще преминава към следващия кадър на всеки няколко секунди докато потребителят не започне ръчно превключване.`,
  XI = `Да не се показва изображение на приложението във фона`,
