  eL = `Изобразяване на бутона „Показване на още“ за мобилни у-ва`,
  tL = `Когато е избрано за мобилни у-ва, ако има достатъчно артикули, така че да се запълни посочения брой редове, ще бъде представен бутон, който да позволява на потребителите да преглеждат оставащите.`,
  nL = `Максимум артикули`,
  rL = `Максималният брой артикули, които да се изобразяват след прилагането на произволна подредба. Това може да бъде използвано, така че да разполагате с голям наличен набор за изобразяване, но да се показва само ограничен брой. 0 означава, че всичко се показва.`,
  iL = `Максимум редове`,
  aL = `Тази секция ще изобразява до толкова редове, преди на потребителя да бъде показан бутона „Показване на още“. Така ще се изобразяват допълнителни артикули.`,
