  $V = `Връзка към „призрачното“ изображение на значката (незадължително)`,
  eH = `Незадължителни активи, които, ако са зададени, ще бъдат показани на потребителя, ПРЕДИ той да придобие действителната значка. Това е полезно, когато искате да скриете специфични подробности за значката преди получаването ѝ. Активът трябва да бъде с размер 160x160 пиксела.`,
  tH = `Добавяне на ниво и адрес`,
