  kH = `Категория на артикула`,
  AH = `Към коя категория принадлежи този артикул. Отварянето на врата предоставя по един артикул от всяка категория, намираща се зад вратата. Ако дадена категория съдържа повече от един артикул, се предоставя само един от тях, избран на случаен принцип. Предоставете собствена категория на всеки артикул, освен ако не е нарочно предвидено артикулите да бъдат алтернативни варианти.`,
