  kG = `Позволява директно редактиране на списъка със свързани артикули за тази разпродажба. Това може да се използва за внасяне или изнасяне от инструменти като Excel, както и за бързото осъществяване на големи промени в списъка с артикули`,
  AG = `Персонализирани етикети`,
  jG = `Позволява директно редактиране на списъка със свързани артикули за тази разпродажба и внасяне и изнасяне конкретно на персонализираната колекция от етикети към артикулите от разпродажбата. Използва се основно за внасяне на подбор от персонализирани етикети, управлявани от външна таблица, без да се модифицират другите етикети на артикулите. Възможно е и внасяне на подклас посредством този диалогов прозорец — това няма да премахне артикули, които не са включени в списъка`,
  MG = `Внасяне от страница за вземане на участие`,
