  Fq = `Пакетът не е позволен`,
  Iq = `Този пакет не може да бъде добавен, защото не е свързан към начална страница за създател (разработчик, издател или поредица). Свържете артикула и презаредете страницата за разпродажба, за да опресните асоциацията. Тези приложения не са свързани към създателя: (%1$s).`,
