  HJ = `Автоматичното генериране на фасети ще презапише всички съществуващи фасети в тази секция. Продължаване?`,
  UJ = `Използвайте функционален етикет за приложения с таг „Контролер“ в магазина.`,
  WJ = `Премахване на неизползваните фасети`,
