  ZJ = `По име`,
  QJ = `По брой съвпадения`,
  $J = `Ръчно`,
  eY = `Име на фасетната стойност. Фасетната стойност е индивидуална опция, на която потребителят може да кликне, за да филтрира игрите, показвани в тази секция. Например: „От първо лице“.`,
  tY = `Незадължителен текст, който ще се появи вдясно от фасетната стойност и ще предостави много кратко обяснение за нея. Например: „1—2 часа“ за фасетна стойност, прилагана към игри с кратко времетраене.`,
  nY = `Име на този фасет. Фасетът е група сродни опции, върху всяка от които потребителят може да кликне, за да филтрира игрите, показвани в тази секция. Например: „Жанр“.`,
  rY = `Автоматично попълва фасетите и фасетните стойности въз основа на категориите за тагове в магазина, като „Жанр“ и „Визия и перспектива“. След автоматичното генериране, ако е нужно можете да редактирате ръчно всеки един фасет и фасетна стойност.`,
  iY = `Премахва всяка фасетна стойност, която не отговаря на никой от артикулите в тази секция.`,
  aY = `Какъв е минималният брой резултати, които искате да получите за всеки избран фасет? Това ще скрие всички термини от лявото меню, които нямат поне този брой съответстващи артикули. Тази бройка се калкулира след прилагането на който и да е филтър на раздела. Обикновено около 5 е добре.`,
  oY = `Показва максимум толкова опции под всяка високопоставена категория в лявото меню. Например, показва не повече от толкова жанрове под фасет с име „Жанр“. Обикновено около 5 е добре.`,
  sY = `Сортира фасетните стойности за всеки фасет според този показател. Обикновено най-доброто сортиране е по брой съвпадения.`,
  cY = `Сортира фасетните стойности в рамките на всеки фасет по азбучен ред според тяхното име.`,
  lY = `Сортира фасетните стойности в рамките на всеки фасет в низходящ ред според броя на съответстващите артикули. Например, за фасет с име „Жанр“, „Ролеви“ ще излиза преди „Стратегии“, ако в тази секция ролевите игри са повече от стратегическите.`,
  uY = `Не сортира фасетните стойности. Те ще бъдат показвани по реда, определен в списъците по-долу.`,
  dY = `Подчертан цвят на фасет`,
  fY = `Цвят на заглавие`,
  pY = `Активирано по подразбиране`,
  mY = `Синхронизиране на 20-те най-популярни тага от магазина`,
  hY = `По подразбиране, само най-популярните 10 тага от магазина са синхронизирани за всеки артикул. Поставете отметка в това поле, ако предпочитате да синхронизирате най-популярните 20 тага.`,
  gY = `Генериране на информация за отстраняване на неизправности`,
  _Y = `Логическо „И“`,
  vY = `Ако е поставена отметка, при избор на множество фасетни стойности в този фасет се прилага логическото „И“ на избраните филтри за фасетни стойности. В противен случай се прилага логическото „ИЛИ“ на избраните филтри за фасетни стойности.`,
  yY = `Първоначално разширено`,
  bY = `Ако е поставена отметка, този фасет се разширява, когато браузърът се появи за пръв път.`,
  xY = `Единично избиране`,
  SY = `Ако е поставена отметка, избирането на този фасет ще премахне избора от останалите.`,
  CY = `Настройки за произход на артикула (незадължително)`,
  wY = `Вместо да посочвате специфичен списък със свързани приложения, можете да определите име на център за съдържание, от който да бъдат извеждани артикулите за тази разпродажба. Ако е избрано, списъкът със свързани приложения за разпродажбата ще бъде игнориран, а страницата за разпродажбата ще показва всичко от дадения център за съдържание.`,
  TY = `Тип център за съдържание`,
  EY = `Категория`,
  DY = `Таг`,
  OY = `Включване само на намалени и безплатни за пускане артикули`,
  kY = `Произход на артикула`,
