  jY = `Център за съдържание`,
  MY = `Заглавие на център за съдържание`,
  NY = `Главна ротационна капсула на центъра за съдържание`,
  PY = `Вторични ротационни капсули на центъра за съдържание`,
  FY = `Определение за артикул (виртуални артикули)`,
  IY = `Виртуални артикули, посочени в играта и управлявани от услугата за Steam инвентар или от специфична за играта услуга за икономически активи, притежавана от партньор`,
  LY = `Избрани виртуални артикули:`,
  RY = `Максимално разрешено количество`,
  zY = `Брой на виртуалните артикули от този тип, които могат да бъдат закупени едновременно. Задайте към нула или едно, за да преустановите падащото меню за количеството.`,
  BY = `Преглед на магазина за артикули на приложението`,
  VY = `Добавяне на виртуален артикул`,
  HY = `Можете да заредите или отмените художественото творчество по подразбиране, асоциирано с виртуалния артикул. В противен случай ние използваме изображението, което би се виждало в магазина за артикули във връзка с виртуалния артикул`,
  UY = `Заявяване на безплатен артикул`,
  WY = `Секция, която позволява на потребителя да заяви безплатен артикул. Това ще разкрие кога може да заяви следващия артикул (ако има такъв). Може да се използва за ежедневното падане на артикули. Това е обвързано към наградната джаджа, за да се установи технологията за заявяване артикул от разпродажба.`,
  GY = `Незадължително — Въведете име на бутона за заявяване`,
  KY = `Ако не е въведено, ще използваме името на бутона по подразбиране.`,
  qY = `Личен календар`,
