  tX = `Напред`,
  nX = `Назад`,
  rX = `ЧЗВ`,
  iX = `Изобразяване на въпроси с отговорите им. Изобразяват се един след друг или един до друг.`,
  aX = `Списък с технически спецификации`,
  oX = `Показване на технологичен блок с позиции за всяка техническа спецификация.`,
  sX = `Решетка за медийно съдържание`,
  cX = `Позволяваща персонализиране мрежа от медийни елементи с описания. Всякакъв брой редове с до 5 колони за ред. Броят на колоните може да се променя за всеки ред.`,
  lX = `Медиен слой`,
  uX = `Медийни елементи (видеа/изображения) като основен фокус със способността за наслагване на текст върху изображението.`,
  dX = `Steam рецензии`,
  fX = `Показване на Steam рецензиите за дадено приложение и позволяване на клиентите да напишат такава.`,
  pX = `Сваляемо съдържание за Вас`,
  mX = `Показва сваляемо съдържание за всички приложения в библиотеката на потребителя. Търси из целия Steam каталог и не се ограничава само до артикулите, изрично изброени в страницата за разпродажба или в списъка със свързани артикули.`,
