  jX = `Последно пускани`,
  MX = `Сортира основните приложения по време на последното им пускане, започвайки с пусканите най-скоро.`,
  NX = `Популярни`,
  PX = `Сортира основните приложения, като първо показва тези с най-популярните сваляеми съдържания. Популярността се определя от ранга по продажби, така че е възможно сваляемите съдържания с нисък такъв да не се показват.`,
  FX = `Макс. последно пускане (месеци)`,
