  LX = `Мин. игрално време (часове)`,
  RX = `Показване само на сваляемо съдържание за игри, пускани от потребителя за поне толкова часа.`,
  zX = `Основни приложения за показване`,
  BX = `При зареждане на страницата се показва само сваляемо съдържание за толкова игри. Ще бъде изобразен бутон „Показване на още“, ако има сваляемо съдържание за още игри.`,
  VX = `Скриване на статистики от сваляемо съдържание`,
  HX = `Ако е поставена отметка, резюмето на статистиките от сваляемо съдържание, притежавано от и достъпно за потребителя, няма да се показва в горната част на тази секция.`,
  UX = `Steam поддръжка`,
  WX = `Съжаляваме, но не успяхме да намерим тази страница.`,
  GX = `Връщане към началната страница за общността`,
  KX = `Връзки за администратор`,
  qX = `Последно обновени: %2$s, от %1$s`,
  JX = `Редактиране на ЧЗВ`,
  YX = `Черновата, редактирана от %1$s, има скорошни промени; последно запазване: %2$s`,
