  oZ = `Редактиране на ЧЗВ:`,
  sZ = `Преглеждане на ЧЗВ:`,
  cZ = `Съжаляваме, но не успяхме да намерим тази страница.`,
  lZ = `Към таблото`,
  uZ = `Изберете един или повече файлове за качване, така че да внесете локализиран текст за заглавието и основния Ви текст. Използваме разширението, за да определим дали внасяният файл е XML или CSV. При XML използваме приложно програмен интерфейсен (API) езиков код в края на файловото име преди разширението. Така определяме езика за съдържанието на XML файла. Трябва да стартирате с изнасянето на CSV или XML, за да се уверите, че използвате правилния формат.`,
  dZ = `Изнася настоящия език в един файл от избрания тип. XML винаги генерира отделен файл на настоящия език на редактора. CSV ще изнесе всички налични езици заедно в един файл.`,
  fZ = `Изображения`,
  pZ = `Редактиране на ЧЗВ`,
  mZ = `Изтриване на ЧЗВ…`,
  hZ = `Перманентно изтриване на този ЧЗВ.`,
  gZ = `Изтриването на постъпление в ЧЗВ е незабавно и не може да бъде отменено.  Сигурни ли сте, че искате да изтриете тази статия и цялото ѝ езиково съдържание?`,
  _Z = `Изтриване на ЧЗВ; моля, изчакайте`,
