  bZ = `Редактиране…`,
  xZ = `Изберете опциите тук, за да направите ЧЗВ видими в желаната област. Видимостта изисква също публикувана версия на заявения език или на алтернативен език, подходящ за областта.`,
  SZ = `Видимостта в областите за ЧЗВ може да бъде променена чрез този диалогов прозорец. Ако документът няма видимост, то той няма да бъде достъпен, дори ако е публикуван.`,
