  EZ = `Видимо в „Steam China“ („Steam | Китай“)`,
  DZ = `Забележка: Изисква се съдържанието да бъде локализирано и публикувано на опростен китайски или опростен китайски за „Steam China“ („Steam | Китай“), за да има съдържанието реална видимост в „Steam China“ („Steam | Китай“)`,
  OZ = `Преглед на текущ ЧЗВ`,
