  jZ = `Публикуване…`,
  MZ = `Публикувайте чернови на един или повече езика във версията за широката публика. Забележете, че видимостта се контролира отделно от публикуваните версии`,
  NZ = `Изисква се да запазите, преди да започнете процеса на публикуване`,
  PZ = `Тече процес на публикуване на ЧЗВ. Моля, изчакайте…`,
  FZ = `Успешно завършване на публикуването.`,
  IZ = `При публикуване се взема черновата версия, която става текущата версия. Следните езици са с променена чернова версия. Изберете кои да публикувате сега.`,
